let valor = String(msg.payload || "").trim();
let match = valor.match(/\/p\/([^\/]+)/);
let targetId = match ? match[1] : (valor && valor !== "true" && valor !== "all" ? valor : null);

let procesados = global.get("posts_procesados") || [];

if (targetId) {
  let antes = procesados.length;
  let filtrados = procesados.filter(id => id !== targetId);
  global.set("posts_procesados", filtrados);
  node.warn("🧹 Post eliminado de memoria: " + targetId + " (antes: " + antes + ", ahora: " + filtrados.length + ")");
} else {
  global.set("posts_procesados", []);
  node.warn("🔄 Memoria reseteada completamente. Posts procesados: 0");
}

return msg;

const APIFY_TOKEN = "apify_api_9WmTdXVQJgFLeh68xTnPKvLxIApaYL3DR3BC";
const postUrl = String(msg.payload).trim();

if (!postUrl.includes("instagram.com/p/")) {
    node.error("La URL debe ser de una publicación de Instagram (ej: /p/XXXXX/)");
    return null;
}

// Limpiar este post puntual de YA PROCESADOS para que el test manual siempre lo analice
const match = postUrl.match(/\/p\/([^\/]+)/);
if (match && match[1]) {
  const shortCode = match[1];
  let procesados = global.get("posts_procesados") || [];
  global.set("posts_procesados", procesados.filter(id => id !== shortCode));
  node.warn("🧹 Post " + shortCode + " liberado de memoria para test manual.");
}

msg.url = "https://api.apify.com/v2/acts/apify~instagram-scraper/run-sync-get-dataset-items?token=" + APIFY_TOKEN + "&timeout=120";
