  return null; 
}
node.log("✅ Entre semana (20:00 hs Argentina) — activando pipeline");
return msg;

const APIFY_TOKEN = "apify_api_9WmTdXVQJgFLeh68xTnPKvLxIApaYL3DR3BC";

const PERFILES = [
  "https://www.instagram.com/entretiempo_gualeguay/",
  "https://www.instagram.com/entretiempo_gualeguay.fem/",
  "https://www.instagram.com/entretiempo_inferiores/",
  "https://www.instagram.com/ligafutbolgualeguay/",
  "https://www.instagram.com/barrionortegualeguay/",
];

msg.apify_token = APIFY_TOKEN;
msg.url = "https://api.apify.com/v2/acts/apify~instagram-scraper/run-sync-get-dataset-items?token=" + APIFY_TOKEN + "&timeout=120";
msg.payload = {
  directUrls:   PERFILES,
  resultsType:  "posts",
  resultsLimit: 5,
};
msg.headers = { "Content-Type": "application/json" };
node.log("Iniciando Apify para " + PERFILES.length + " perfiles...");
return msg;

const posts = Array.isArray(msg.payload) ? msg.payload : [];
node.warn("=== PRIMER POST RAW ===");
node.warn(JSON.stringify({
  shortCode:     posts[0] && posts[0].shortCode,
  ownerUsername: posts[0] && posts[0].ownerUsername,
  timestamp:     posts[0] && posts[0].timestamp,
  displayUrl:    posts[0] && (posts[0].displayUrl || "").substring(0, 60),
  caption:       posts[0] && (posts[0].caption || posts[0].captionText || "").substring(0, 80),
}));

node.warn("TODOS LOS POSTS: " + posts.map(function(p) {
  return (p.ownerUsername || p.username || "?") + "/" + (p.shortCode || p.id || "?");
}).join(", "));

node.warn("YA PROCESADOS: " + JSON.stringify(global.get("posts_procesados") || []));
if (posts.length === 0) { node.warn("Apify no devolvió posts."); return null; }

node.log("Apify: " + posts.length + " posts totales.");

let procesados = global.get("posts_procesados") || [];
const setProcesados = new Set(procesados);
const ahora  = Date.now();
const limite = ahora - (48 * 60 * 60 * 1000); // Ventana de 48 hs

const postsNuevos = posts.filter(function(post) {
  const id = post.shortCode || post.id || post.url;
  if (!id || setProcesados.has(id)) return false;
  if (post.timestamp) {
    const fechaPost = new Date(post.timestamp).getTime();
    if (fechaPost < limite) { node.log("Post viejo ignorado: " + id); return false; }
  }
  return true;
});

if (postsNuevos.length === 0) { node.log("Sin posts nuevos."); return null; }
node.log(postsNuevos.length + " posts nuevos detectados.");

// NOTA: Se guardará en memoria solo al confirmar éxito en DB o descarte por IA.

const mensajes = [];

postsNuevos.forEach(function(post) {
  const shortCode = post.shortCode || post.id || "";

  const caption = String(
    post.caption || post.captionText || post.text || post.description || ""
  ).trim().substring(0, 800);

  const imagenesDelPost = [];
  if (post.displayUrl) imagenesDelPost.push(post.displayUrl);

  const fuentes = [post.images, post.childPosts, post.sidecarImages];
  fuentes.forEach(function(fuente) {
    if (!Array.isArray(fuente)) return;
    fuente.forEach(function(item) {
      let url = null;
      if (typeof item === "string")     url = item;
      else if (item && item.displayUrl) url = item.displayUrl;
      else if (item && item.url)        url = item.url;
      else if (item && item.src)        url = item.src;
      if (url && !imagenesDelPost.includes(url)) imagenesDelPost.push(url);
    });
  });

  node.log("Post " + shortCode + ": " + imagenesDelPost.length + " imagen(es) | caption: " + caption.substring(0,40));

  imagenesDelPost.forEach(function(imageUrl, idx) {
    mensajes.push({
      payload:       { image_url: imageUrl },
      image_url:     imageUrl,
      url:           imageUrl,
      post_id:       shortCode,
      post_fecha:    post.timestamp || "",
      post_url:      post.url || (shortCode ? "https://www.instagram.com/p/" + shortCode + "/" : ""),
      cuenta_origen: post.ownerUsername || post.username || "",
      caption:       idx === 0 ? caption : "",
    });
  });
});

node.log("Imágenes a analizar: " + mensajes.length);
return [mensajes];

const p = msg.payload || {};
const imageUrl =
  p.image_url || p.imageUrl || p.url ||
  (p.media && p.media[0] && p.media[0].url) || "";

if (!imageUrl) {
  node.error("No se encontró image_url en el payload", msg);
  return null;
}

msg.image_url = imageUrl;
msg.url       = imageUrl;
msg.payload   = { image_url: imageUrl };

// Preservar cuenta_origen y post_url si vienen del flujo Apify
if (!msg.cuenta_origen) msg.cuenta_origen = "";
if (!msg.post_url)      msg.post_url = "";
if (!msg.post_id)       msg.post_id = "";

node.log("URL: " + imageUrl.substring(0, 80));
return msg;

const buffer = msg.payload;

if (msg.statusCode && msg.statusCode !== 200) {
    node.error("❌ Error descargando imagen: HTTP " + msg.statusCode + ". La URL probablemente expiró (Instagram cambia los links cada 24hs).");
    return null;
}

if (!Buffer.isBuffer(buffer)) {
  node.error("Imagen no llegó como buffer.");
  return null;
}

if (buffer.length < 1000) {
  node.warn("Buffer muy pequeño (" + buffer.length + " bytes) — URL expirada o bloqueada");
  return null;
}

const url = String(msg.url || msg.image_url || "").toLowerCase();
let mimeType = "image/jpeg";
if (url.includes(".png"))  mimeType = "image/png";
if (url.includes(".webp")) mimeType = "image/webp";
if (url.includes(".gif"))  mimeType = "image/gif";

msg.image_base64 = buffer.toString("base64");
msg.image_mime   = mimeType;

node.log("✅ Imagen descargada: " + mimeType + " — " + Math.round(buffer.length / 1024) + " KB");
return msg;

const cuenta = String(msg.cuenta_origen || "").toLowerCase();
const caption = String(msg.caption || "").trim();

const PROMPT = `Sos el sistema inteligente de contenidos y estadísticas del Club Atlético Barrio Norte (Liga Departamental de Fútbol de Gualeguay y disciplinas deportivas del club).

Analizá con precisión la imagen y el texto de la publicación para clasificarla en UNO de los siguientes 3 casos. Respondé ÚNICAMENTE con JSON válido:
{ "tipo_contenido": "noticia" | "resultado" | "descartar", "datos": { ... } }

━━━ CASO 1: NOTICIA DEL CLUB (tipo_contenido = "noticia") ━━━
Aplica si la imagen/publicación trata de una actividad, logro o novedad del CLUB ATLÉTICO BARRIO NORTE (escudo CABN, camiseta albirroja/roja y blanca, mención expresa al club, sus deportistas, directivos o hinchas).
Abarca tanto fútbol como TODAS sus disciplinas deportivas y culturales:
- "Ciclismo" (carreras, podios, circuito, ciclistas del club como Milagros Sanabria)
- "Bochas" (torneos de bochas, parejas, tríos)
- "Tenis" (torneos, dobles, singles, escuelita)
- "Billar" (5 quillas, casín)
- "Gimnasia" (gimnasia rítmica, presentaciones)
- "Fútbol" (Primera División masculina del club)
- "Femenino" (Fútbol femenino del club)
- "Inferiores" (sub-13 a sub-17 del club)
- "Infantiles" (formativas y escuelita del club)
- "Samba Verá" (comparsa, batucada, carnaval del club)
- "Institucional" (sede, socios, obras, aniversarios)

Redacción: Estilo periodístico argentino, natural, conciso y cercano al hincha ("el Norte", "el Norteño", "el finde"). Prohibido lenguaje neutro ("balompié", "zaga", "guardameta").
Formato datos:
{
  "titulo": "Título periodístico directo (máx 8 palabras)",
  "resumen": "Resumen conciso y claro de lo ocurrido (máximo 2 oraciones).",
  "categoria": "[Ciclismo|Bochas|Tenis|Billar|Gimnasia|Fútbol|Femenino|Inferiores|Infantiles|Samba Verá|Institucional]",
  "tags": ["Ciclismo", "Norteños", "Gualeguay"]
}

━━━ CASO 2: RESULTADOS DE PARTIDOS DE LA LIGA (tipo_contenido = "resultado") ━━━
Aplica si la imagen muestra MARCADORES O RESULTADOS DE PARTIDOS jugados en la Liga Departamental de Fútbol de Gualeguay.
IMPORTANTE: Procesá TODOS los partidos que figuren en la imagen, INCLUSO SI NO JUEGA BARRIO NORTE (para poder armar y actualizar tablas de posiciones y llaves de playoffs de toda la liga).
Categorías posibles: "Primera Masculina", "Primera Femenina", "Tercera", "Cuarta", "Quinta", "Sexta", "Séptima".
Fases posibles:
- "Fase Regular" (indicar round_number si dice 'Fecha 1', 'Fecha 8', etc.)
- "Semifinales Ida", "Semifinales Vuelta", "Final Ida", "Final Vuelta"
- "Repechaje", "Petit Torneo"
Nombres de equipos normalizados: Usar nombres oficiales ("Barrio Norte", "Bancario", "Juventud", "Sportiva", "Gualeguay Central", "El Progreso", "La Academia", "Urquiza", "Centro Bancario", "Quilmes").
Formato datos:
{
  "torneo": "Torneo Oficial 2026",
  "categoria": "Primera Masculina",
  "fase": "Fase Regular",
  "round_number": 8,
  "partidos": [
    {
      "local": { "equipo": "Barrio Norte", "goles": 2 },
      "visitante": { "equipo": "Bancario", "goles": 1 }
    }
  ]
}
(Si los goles de algún partido aún no se jugaron o no aparecen, poner "goles": null).

━━━ CASO 3: DESCARTAR (tipo_contenido = "descartar") ━━━
Aplica en cualquiera de estos casos:
- TABLAS DE POSICIONES PURAS (tablas con puntos, PJ, PG, PE, PP, etc., ya que nuestro sistema las calcula matemáticamente a partir de los partidos).
- Publicidades comerciales ajenas sin relación al club.
- Publicaciones exclusivas de clubes rivales que no sean marcadores de partidos de la liga.
- Memes o imágenes sin información noticiable ni deportiva.
Formato datos:
{
  "motivo": "Explicación breve del descarte"
}`;

msg.gemini_intentos = msg.gemini_intentos || 1;
msg.gemini_modelo = "gemini-3.1-flash-lite";
const API_KEY = "AIzaSyAMYKaj8_lLSpYGX-LnWQlmj7HDCiEyTYo";
msg.url = `https://generativelanguage.googleapis.com/v1beta/models/${msg.gemini_modelo}:generateContent?key=${API_KEY}`;

msg.payload = {
  contents: [{
    parts: [
      { inlineData: { mimeType: msg.image_mime || "image/jpeg", data: msg.image_base64 } },
      { text: PROMPT + "\n\nCUENTA ORIGEN: " + cuenta + "\nTEXTO DE LA PUBLICACIÓN:\n" + caption }
    ]
  }],
  generationConfig: { temperature: 0.1, response_mime_type: "application/json", maxOutputTokens: 1024 }
};

node.log("📤 Preparando Gemini (Modelo: " + msg.gemini_modelo + " - Intento " + msg.gemini_intentos + ") | cuenta: " + cuenta);
return msg;

const payload = msg.payload || {};
const statusCode = msg.statusCode || 200;
const errorCode = (payload.error && payload.error.code) || (statusCode >= 400 ? statusCode : null);

// 1. Éxito: tiene candidates válidos
if (!errorCode && payload.candidates && payload.candidates.length > 0) {
  node.log("✅ Gemini respondió OK con modelo: " + (msg.gemini_modelo || "gemini-3.1-flash-lite"));
  return [msg, null]; // Salida 1: Continúa a Parsear respuesta
}

// 2. Error (503 alta demanda, 429 cuota momentánea, etc.)
const intentos = msg.gemini_intentos || 1;
const errorMsg = (payload.error && payload.error.message) || ("HTTP " + statusCode);
node.warn(`⚠️ Error en ${msg.gemini_modelo || "Gemini"} (Intento ${intentos}): ${errorMsg}`);

const API_KEY = "AIzaSyAMYKaj8_lLSpYGX-LnWQlmj7HDCiEyTYo";

// Intento 1 falló -> Reintentar con el MISMO gemini-3.1-flash-lite tras pausa de 12s
if (intentos === 1) {
  node.warn("⏳ Reintento 1: Pausa de 12 segundos para superar pico de demanda en 3.1 Flash Lite...");
  msg.gemini_intentos = 2;
  msg.delay = 12000;
  msg.url = `https://generativelanguage.googleapis.com/v1beta/models/gemini-3.1-flash-lite:generateContent?key=${API_KEY}`;
  return [null, msg]; // Salida 2: al delay y vuelve a Gemini
}

// Intento 2 falló -> Segundo reintento con pausa de 15s adicional
if (intentos === 2) {
  node.warn("⏳ Reintento 2: Pausa de 15 segundos adicional en 3.1 Flash Lite...");
  msg.gemini_intentos = 3;
  msg.delay = 15000;
  msg.url = `https://generativelanguage.googleapis.com/v1beta/models/gemini-3.1-flash-lite:generateContent?key=${API_KEY}`;
  return [null, msg]; // Salida 2: al delay y vuelve a Gemini
}

// Si fallaron los 3 intentos:
node.error("❌ Fallaron los reintentos temporales de Gemini. El post NO se quema para reintentarlo en el siguiente ciclo.");
return [null, null];

try {
  const payload   = msg.payload || {};
  const errorCode = payload.error && payload.error.code;

  if (errorCode) {
    throw new Error("Error Gemini " + errorCode + ": " + (payload.error.message || "").substring(0, 120));
  }

  const candidates = payload.candidates;
  if (!candidates || !candidates[0]) {
    throw new Error("Sin candidates en respuesta de Gemini");
  }

  let texto = candidates[0].content.parts[0].text || "";

  // Log para diagnóstico
  node.warn("GEMINI RAW: " + texto.substring(0, 300));

  texto = texto.replace(/```json\s*/gi, "").replace(/```\s*/g, "").trim();

  const parsed = JSON.parse(texto);

  msg.tipo_contenido = parsed.tipo_contenido || "descartar";
  msg.datos          = parsed.datos || {};

  // Si datos está vacío Y tipo no es descartar → problema real, loguear
  if (Object.keys(msg.datos).length === 0) {
    if (msg.tipo_contenido !== "descartar") {
      node.warn("Gemini devolvió datos vacíos para tipo: " + msg.tipo_contenido + " — forzando descartar");
      msg.tipo_contenido = "descartar";
    }
    msg.datos = { motivo: "Sin datos" };
  }

  node.log("✅ Tipo: " + msg.tipo_contenido +
    (msg.datos.categoria ? " | Cat: " + msg.datos.categoria : "") +
    (msg.datos.partidos  ? " | Partidos: " + msg.datos.partidos.length : ""));

} catch(e) {
  node.error("❌ " + e.message);
  msg.tipo_contenido = "descartar";
  msg.datos = { motivo: e.message.substring(0, 100) };
}

return msg;

const imageUrl = msg.image_url || "";
if (!imageUrl) {
