const datos = msg.noticia_datos;
const postUrl = msg.noticia_postUrl;
const cloudinaryUrl = msg.payload.secure_url;

if (!cloudinaryUrl) {
    node.error("Fallo la subida a Cloudinary: " + JSON.stringify(msg.payload));
    return null;
