const authCredentials = Buffer.from("galgo:25deMayo1223").toString("base64");
msg.headers = {
    "Content-Type": "application/json",
    "Authorization": "Basic " + authCredentials
};

node.log("✅ Enviando noticia a la DB en PROD: " + datos.titulo);
return msg;

const datos = msg.datos || {};

if (!datos.partidos || !Array.isArray(datos.partidos) || datos.partidos.length === 0) {
    node.warn("No se detectaron partidos válidos en la imagen.");
    return null;
}

// Lógica de ruteo de TournamentId según categoría
let tournamentId = "oficial-2026";
const cat = String(datos.categoria || "").toLowerCase();
if (cat.includes("femenina") || cat.includes("fem")) {
    tournamentId = "oficial-2026-fem";
} else if (cat.includes("tercera") || cat.includes("3ra")) {
    tournamentId = "tercera-oficial-2026";
} else if (cat.includes("cuarta") || cat.includes("4ta")) {
    tournamentId = "cuarta-oficial-2026";
} else if (cat.includes("quinta") || cat.includes("5ta")) {
    tournamentId = "quinta-oficial-2026";
} else if (cat.includes("sexta") || cat.includes("6ta")) {
    tournamentId = "sexta-oficial-2026";
} else if (cat.includes("séptima") || cat.includes("septima") || cat.includes("7ma")) {
    tournamentId = "septima-oficial-2026";
} else if (cat.includes("cat_a") || cat.includes("cat a")) {
    tournamentId = "cat_a-oficial-2026";
} else if (cat.includes("cat_b") || cat.includes("cat b")) {
    tournamentId = "cat_b-oficial-2026";
} else if (cat.includes("cat_c") || cat.includes("cat c")) {
    tournamentId = "cat_c-oficial-2026";
}

// Lógica de PhaseSlug según la fase
const fase = String(datos.fase || "").toLowerCase();
let phaseSlug = "fase-regular";
if (fase.includes("semi")) {
    phaseSlug = "semifinales";
} else if (fase.includes("petit")) {
    phaseSlug = "petit";
} else if (fase.includes("final")) {
    phaseSlug = "playoffs";
}

let roundNum = null;
if (datos.round_number !== null && datos.round_number !== undefined && datos.round_number !== "") {
    const parsed = parseInt(datos.round_number, 10);
    if (!isNaN(parsed)) roundNum = parsed;
}

msg.payload = {
    tournamentId: tournamentId,
    phaseSlug: phaseSlug,
    roundName: datos.fase || (roundNum ? "Fecha " + roundNum : "Fecha"),
    roundNumber: roundNum,
    partidos: datos.partidos
};

// Endpoint en producción de Netlify
msg.url = "https://clubbarrionorte.netlify.app/api/pipeline/webhook-partidos";
const token = "barrionorte2027";
msg.headers = {
    "Content-Type": "application/json",
    "Authorization": "Bearer " + token
};

node.log("✅ Enviando " + datos.partidos.length + " partidos (" + tournamentId + " | " + phaseSlug + ") al webhook de DB");
return msg;

if (msg.statusCode && msg.statusCode >= 400) {
  node.error("❌ Error guardando en DB: HTTP " + msg.statusCode);
  return null;
}
if (msg.post_id) {
  let procesados = global.get("posts_procesados") || [];
  if (!procesados.includes(msg.post_id)) {
    global.set("posts_procesados", procesados.concat([msg.post_id]).slice(-200));
    node.log("💾 Post " + msg.post_id + " registrado en YA PROCESADOS tras éxito en DB.");
  }
}
return msg;

if (msg.post_id) {
  let procesados = global.get("posts_procesados") || [];
  if (!procesados.includes(msg.post_id)) {
    global.set("posts_procesados", procesados.concat([msg.post_id]).slice(-200));
    node.log("🗑 Post " + msg.post_id + " registrado en YA PROCESADOS (descartado por IA).");
  }
}
return msg;
